URGENT_KEYWORDS = ("urgent", "verify now", "suspended", "immediately")


def phishing_indicators(email):
    indicators = []
    if email["from_domain"] != email["reply_to_domain"]:
        indicators.append("reply_to_domain_mismatch")
    subject_lower = email["subject"].lower()
    if any(keyword in subject_lower for keyword in URGENT_KEYWORDS):
        indicators.append("urgency_language")
    if email["claimed_domain"] not in email["from_domain"]:
        indicators.append("sender_domain_spoofed")
    return indicators


emails = [
    {
        "from_display": "IT Support",
        "from_domain": "corp-security-alerts.net",
        "reply_to_domain": "mail-response.ru",
        "claimed_domain": "whetzy.com",
        "subject": "Your account will be suspended - verify now",
    },
    {
        "from_display": "Ada Lovelace",
        "from_domain": "whetzy.com",
        "reply_to_domain": "whetzy.com",
        "claimed_domain": "whetzy.com",
        "subject": "Notes for tomorrow's meeting",
    },
]

for i, email in enumerate(emails, start=1):
    flags = phishing_indicators(email)
    result = ", ".join(flags) if flags else "sin_indicadores"
    print(f"correo_{i}: {result}")
